/* Lot 102: timeline-scope (generated by scripts/lot102_gen.py; expectations from scripts/lot102_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[256];
static wf_csstl_t g_t[8];

static const char *tp(const char *v, int max) {
    int n, k, m;
    memset(g_t, 0x5a, sizeof(g_t));
    n = wf_csstl_parse(WF_CSSTL_SCOPE, v, g_t, max);
    for (k = n < 0 ? 8 : n; k < 8; k++) if (g_t[k].axis != 0x5a) return "WRITTEN";
    if (n < 0) return "-1";
    m = snprintf(g_o, sizeof(g_o), "%d:", n);
    for (k = 0; k < n && m < (int)sizeof(g_o); k++)
        m += snprintf(g_o + m, sizeof(g_o) - (size_t)m, " %s/%d", g_t[k].name[0] ? g_t[k].name : "-", g_t[k].axis);
    return g_o;
}

static void test_l102_scope_0(void) {
    TEST_ASSERT_EQUAL_STRING("1: -/1", tp("all", 8));
    TEST_ASSERT_EQUAL_STRING("2: --t/0 --v/0", tp("--t , --v", 2));
    TEST_ASSERT_EQUAL_STRING("3: --t/0 --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy/0 --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy/0", tp("--t,--yyyyyyyyyyyyyyyyyyyyyyyyyyyyy,--yyyyyyyyyyyyyyyyyyyyyyyyyyyyy", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp("--t, inherit", 0));
    TEST_ASSERT_EQUAL_STRING("2: --t/0 --u/0", tp("--t,--u", 8));
    TEST_ASSERT_EQUAL_STRING("1: -/1", tp("all", 1));
    TEST_ASSERT_EQUAL_STRING("1: --t/0", tp("--t", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp("all, all", 8));
    TEST_ASSERT_EQUAL_STRING("-1", tp("all none", 4));
    TEST_ASSERT_EQUAL_STRING("1: -/1", tp("all", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp("--t, scroll(), --a.b, --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy, --zzzzzzzzzzzzzzzzzzzzzzzzzzzzzz", 1));
    TEST_ASSERT_EQUAL_STRING("1: -/1", tp("all", 3));
}

